from collections import deque

def get_girth_fast(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        queue = deque([start])
        while queue:
            u = queue.popleft()
            if dist[u] >= min_cycle // 2:
                break
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def circulant_graph(n, offsets):
    edges = set()
    adj = [set() for _ in range(n)]
    for u in range(n):
        for s in offsets:
            v = (u + s) % n
            if u != v:
                e = (min(u,v), max(u,v))
                if e not in edges:
                    edges.add(e)
                    adj[u].add(v)
                    adj[v].add(u)
    return list(edges), adj

# Try all pairs
print("Pairs with girth >= 6:")
for s1 in range(1, 11):
    for s2 in range(s1+1, 11):
        edges, adj = circulant_graph(21, [s1, s2])
        g = get_girth_fast(adj, 21)
        if g >= 6:
            print(f"  C(21, [{s1},{s2}]): {len(edges)} edges, girth {g}")

print("\nTriples with girth >= 7:")
